import json,sys
O=sys.argv[1]; C="tracosdamor"; W="tracosdamor-2026-10-19"; NOW="2026-10-11T18:00:00.000Z"
def st(intencao,estrategia,tema,texto,comoFazer,media="video",inspiracao=""):
  return dict(intencao=intencao,estrategia=estrategia,tema=tema,texto=texto,comoFazer=comoFazer,inspiracao=inspiracao,media=media,linkCriativo="",linkDrive="")
def card(sufixo,data,tipo,titulo,formato=None,stories=(),**k):
  base=dict(cliente=C,data=data,semana=W,tipo=tipo,formato=formato,titulo=titulo,intencao="",estrategia="",tema="",comoFazer="",inspiracao="",legenda="",
    linkCriativo="",capaCriativo="",linkDrive="",capaDrive="",etapa="ideia",origem="claude",criadoEm=NOW,
    historico=[{"etapa":"ideia","por":"claude","em":NOW}],stories=list(stories))
  base.update(k); json.dump(base,open(f"{O}/{C}-{data}-{sufixo}.json","w"),ensure_ascii=False)
NARRA="Como gravar a voz: a Sílvia grava no telemóvel, num quarto com cortinas ou roupa à volta (absorve o eco), a 20 cm da boca, sem música. Lê devagar, com pausas onde há mudança de linha. Faz 2 ou 3 tentativas e envia todas à Ângela. A Sílvia não precisa de aparecer: mãos, costas ou nada."
card("v19","2026-10-19","Feed","Segunda: Feed","Reel",
 intencao="Lançar a camisa e a calça de outono pela voz de quem as desenhou. Antes de ver a peça, a mãe ouve porquê ela existe.",
 estrategia="Até aqui a marca falou por textos no ecrã. A voz da Sílvia muda o registo: é uma pessoa, não uma marca, a explicar uma escolha. O manual pede sensação antes de característica, e a narração começa pelo toque. É o primeiro de dois reels narrados na semana: este diz porquê, o de sexta diz para quê. Preço na legenda e no último frame.",
 tema="Primeiro foi o toque.",
 comoFazer=f"Reel vertical de 30 a 35 segundos, ao ritmo da voz.\nNarração da Sílvia (texto exato):\n\"Quando escolho um tecido, fecho os olhos.\nSe não é bom na mão, não é bom na pele de uma criança.\nEsta camisa começou assim.\nDepois veio a calça.\nPara o chão da sala, para o banco do parque, para o colo da avó.\nNão as fiz para ficarem bem numa fotografia.\nFi-las para durarem o outono inteiro.\nE o seguinte.\"\nImagem, por ordem: 1) mãos da Sílvia a passar no tecido da camisa (grande plano); 2) a camisa no cabide, luz de janela; 3) a calça dobrada, mãos a desdobrar; 4) criança a vestir a camisa sozinha; 5) criança a correr ou sentada no chão com as duas peças; 6) último frame parado: as duas peças lado a lado.\nLegendas da narração no ecrã, na letra Patrick Hand, uma linha de cada vez. Último frame: \"Camisa [preço] € · Calça [preço] €\" e \"Comenta OUTONO\".\n{NARRA}\nMontagem: Ângela. Este é o reel com anúncio (5 a 10 € por dia) até quarta.",
 inspiracao="Referência descrita: reels de marcas de autor em que a fundadora narra o processo com voz baixa e imagens de mãos e tecido. Copiar a calma: pouca música por baixo, a voz à frente, cortes ao fim de cada frase.",
 legenda="Primeiro foi o toque.\nSe não é bom na mão, não é bom na pele de uma criança.\n\nA camisa e a calça de outono.\nPara o chão da sala, o banco do parque, o colo da avó.\n\nCamisa [preço] € · Calça [preço] € · tamanhos [tamanhos]\n\nComenta OUTONO e envio-te as medidas e o link.\n\nCada peça começa com intenção e termina em memória.",
 stories=[st("Levar quem viu o reel até à peça, pela textura.","Depois da voz, o toque: um vídeo de perto do tecido responde à pergunta que a narração deixou (como é?). Link direto, sem mais nada.","Toca-lhe.","Toca-lhe.\nCamisa [preço] € · link aqui.","Vídeo vertical de 5 segundos: mão a passar devagar no tecido da camisa, luz natural lateral. Texto no topo: \"Toca-lhe.\" Em baixo, link sticker \"Ver a camisa\" para [link]. Sem música.")])
card("v20","2026-10-20","Storie","Terça: Storie",
 stories=[st("Tirar a dúvida que mais trava a compra online: o tamanho.","Tabela em cm e uma caixa de pergunta: a mãe escreve a idade e a altura, a Sílvia responde por mensagem com o tamanho e o link. Cada resposta é uma conversa de venda.","Medidas em cm.","Medidas reais, em cm.\nDiz-me a idade e a altura, eu digo-te o tamanho.","Foto da tabela de medidas da camisa e da calça em design limpo (Patrick Hand, fundo sálvia). Caixa de pergunta: \"Idade e altura?\". Responder a cada uma por mensagem em menos de 1 hora, com o tamanho, foto e link.",media="foto"),
  st("Pôr a mãe a imaginar a criança com a peça, com um toque fácil.","Sondagem de duas opções: não pede nada e mantém a camisa na cabeça de quem respondeu. Quem responde recebe depois uma mensagem pessoal da Sílvia.","Por dentro ou por fora?","Camisa por dentro ou por fora?","Duas fotos lado a lado da mesma criança: camisa por dentro da calça e camisa por fora. Sondagem: \"Por dentro\" / \"Por fora\". No fim do dia, a Sílvia manda mensagem a quem votou: \"Obrigada por votares. Se quiseres ver as medidas, envio-te.\"",media="foto")])
card("v21","2026-10-21","Feed","Quarta: Feed","Carrossel",
 intencao="Mostrar que o par camisa + calça serve a semana toda, e com o Casaco Trilha por cima.",
 estrategia="O reel de segunda deu a razão; o carrossel dá a utilidade. Três situações reais em vez de três looks de catálogo. O último slide junta os preços e o pedido: a mãe que guardou o post tem tudo para decidir. A terceira situação (jantar dos avós) abre a porta ao Natal sem o dizer.",
 tema="Uma camisa. Uma calça. Três dias.",
 comoFazer="Carrossel de 5 slides, 4:5.\nSlide 1 (capa): \"Uma camisa. Uma calça. Três dias.\" sobre foto das duas peças no cabide.\nSlide 2: \"Terça, escola.\" Criança de mochila, camisa por fora.\nSlide 3: \"Sábado, mato.\" Camisa e calça com o Casaco Trilha por cima, ao ar livre.\nSlide 4: \"Domingo, jantar dos avós.\" Camisa por dentro, cabelo penteado, mesa posta ao fundo.\nSlide 5: \"Camisa [preço] € · Calça [preço] € · Casaco Trilha [preço] €\" e \"Comenta OUTONO\".\nTítulos em Blueberry, texto pequeno em Patrick Hand. Fotos da sessão de outono [confirmar se já existem; se não, 3 fotos na sessão de quinta].",
 inspiracao="Referência descrita: carrosséis de \"uma peça, três usos\" de marcas de moda infantil europeias, com uma foto por situação e texto mínimo no canto.",
 legenda="Terça, escola.\nSábado, mato.\nDomingo, jantar dos avós.\n\nA mesma camisa. A mesma calça.\nO outono não pede mais peças. Pede peças que aguentem.\n\nCamisa [preço] € · Calça [preço] €\n\nComenta OUTONO e envio-te o link.",
 stories=[st("Levar o carrossel a quem não o viu no feed.","Partilha com um só pedido: ver o post. Sem repetir o texto todo.","Três dias.","Três dias com as mesmas duas peças.\nVê no feed.","Partilha do carrossel nos stories com sticker \"Ver publicação\" e uma linha: \"Três dias com as mesmas duas peças.\" Link sticker para a página da camisa.",media="foto")])
card("v22","2026-10-22","Storie","Quinta: Storie",
 stories=[st("Mostrar o processo com a voz da Sílvia, para dar valor antes de pedir.","O manual diz: nada é \"só produção\". Um bastidor narrado em 15 segundos prova a qualidade sem adjetivos.","A parte que ninguém vê.","A parte que ninguém vê.","Vídeo de 15 segundos na produção ou no atelier: mãos a cortar, a coser uma casa de botão, a dobrar a camisa. Por cima, áudio da Sílvia (texto exato): \"Esta é a parte que ninguém vê. É aqui que a peça decide se vai durar um ano ou cinco.\" Legenda da frase no ecrã."),
  st("Converter quem viu o bastidor.","Depois do processo, o preço já não assusta: foi explicado. Link direto.","Já está no site.","Camisa [preço] € · Calça [preço] €\nTamanhos [tamanhos]\nJá está no site.","Foto das duas peças dobradas, fundo amarelo-claro do manual (#F0E2B2). Texto com preços e tamanhos. Link sticker \"Levar as duas\" para [link].",media="foto")])
card("v23","2026-10-23","Feed","Sexta: Feed","Reel",
 intencao="Segundo reel narrado: a Sílvia explica para que é a calça, a partir da vida real de uma criança.",
 estrategia="Segunda foi o porquê (o toque). Sexta é o para quê (o uso). A frase \"as calças de uma criança não vivem de pé\" é uma verdade que a mãe reconhece logo, e põe a qualidade num sítio concreto: os joelhos. Sexta à tarde é quando se decide a compra do fim de semana; o anúncio passa para este reel.",
 tema="As calças de uma criança não vivem de pé.",
 comoFazer=f"Reel vertical de 25 a 30 segundos.\nNarração da Sílvia (texto exato):\n\"As calças de uma criança não vivem de pé.\nVivem de joelhos.\nNo chão da sala, a construir.\nNas folhas, a procurar.\nNo escorrega, a descer outra vez.\nPor isso comecei pelos joelhos.\n[detalhe de construção a confirmar com a Sílvia: reforço, costura, tecido]\nO resto foi fácil.\"\nImagem, por ordem: criança de joelhos no chão da sala com legos; joelhos nas folhas; descida no escorrega; grande plano dos joelhos da calça; criança a levantar-se e a correr. Último frame: \"Calça [preço] €\" e \"Comenta OUTONO\".\nLegendas da narração no ecrã, uma linha de cada vez.\n{NARRA}\nAnúncio: passa para este reel de sexta a domingo.",
 inspiracao="Referência descrita: reels de produto narrados em primeira pessoa, com planos à altura da criança e som ambiente baixo por baixo da voz.",
 legenda="As calças de uma criança não vivem de pé.\nVivem de joelhos.\n\nPor isso comecei por aí.\n\nCalça [preço] € · tamanhos [tamanhos]\nCom a camisa: [preço das duas] €\n\nComenta OUTONO e envio-te as medidas e o link.",
 stories=[st("Fechar a semana com preço antes do fim de semana.","Um ecrã, uma decisão: o link. A frase do reel repete-se para quem só vê stories.","Vivem de joelhos.","As calças de uma criança não vivem de pé.\nCalça [preço] € · link aqui.","Frame do reel (criança de joelhos). Texto no topo com a frase. Link sticker \"Ver a calça\" para [link]. Responder a DMs em menos de 1 hora.")])
card("v24","2026-10-24","Storie","Sábado: Storie",
 stories=[st("Primeira menção ao Natal, sem vender: pôr a ideia da foto de família na cabeça.","Uma pergunta suave a dois meses do Natal. A resposta diz-nos quem está a pensar em presentes e roupa de festa, para a lista VIP de novembro.","A foto deste Natal.","Já pensaste na foto de família deste Natal?","Foto antiga ou de arquivo de uma mesa de Natal, luz quente (sem crianças a posar). Sondagem: \"Já pensei\" / \"Ainda não\". Quem responde \"Já pensei\" recebe mensagem da Sílvia na segunda.",media="foto"),
  st("Ligar a camisa à ocasião, sem pedir compra.","Mostra a camisa como opção para a foto, mas o pedido é só uma caixa de pergunta: abre conversa.","Camisa de domingo.","Esta é a minha camisa preferida para a foto.\nO que vão vestir os teus?","A Sílvia (mão ou de costas) segura a camisa no cabide junto à janela. Texto na voz dela. Caixa de pergunta: \"O que vão vestir?\".",media="foto")])
card("v25","2026-10-25","Storie","Domingo: Storie",
 stories=[st("Antecipar a semana das três peças (26/10 a 1/11).","Teaser com data real: a próxima semana junta o Casaco Trilha, a camisa e a calça, com condição até 1 de novembro. Lembrete para não perder.","As três juntas.","Para a semana, as três juntas.\nCasaco Trilha, camisa e calça.","Vídeo de 5 segundos: as três peças a aparecerem uma a uma no mesmo cabide. Texto: \"Para a semana, as três juntas.\" Sticker de lembrete: \"As três juntas, segunda às 10h\"."),
  st("Dar a condição com data real, sem urgência inventada.","A condição é verdadeira e tem fim: 1 de novembro às 23h59. Dita uma vez, com calma.","Até 1 de novembro.","Casaco Trilha + camisa + calça: [preço das três] €\naté 1 de novembro, às 23h59.\nEmbrulho de oferta e portes grátis.","Foto das três peças dobradas umas sobre as outras, fundo terracota claro. Texto com a condição. Link sticker para [link do conjunto]. [Confirmar com a Sílvia o preço das três.]",media="foto")])
